//! Authenticated resident control surface. No caller-provided runtime facts,
//! executable paths, bundle fingerprints or managed policy are accepted.
use crate::context_assistance_service::Check;
use crate::guard_config_load::AssistanceSettings;
use crate::package_authority_op::request_digest_with_limit;
use crate::policy_store::PolicySnapshotStore;
use serde::{Deserialize, Serialize};
use serde_json::json;
use std::path::Path;

pub(crate) const FEATURE: &str = "context-assistance-control-v2";
pub(crate) const WORKSPACE_FEATURE: &str = "context-assistance-workspaces-v1";
pub(crate) const ACTION_FEATURE: &str = "context-assistance-native-decisions-v1";
pub(crate) const HISTORY_FEATURE: &str = "context-assistance-history-v1";

#[derive(Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct Request {
    schema: String,
    request_id: String,
    pub(crate) query: Query,
}
#[derive(Clone, Copy, Debug, Deserialize, Serialize)]
#[serde(rename_all = "snake_case")]
pub(crate) enum Kind {
    Status,
    Installations,
    Recheck,
    Activate,
    Stop,
    Workspace,
    WorkspaceAccess,
    WorkspaceGrant,
}
impl Kind {
    fn name(self) -> &'static str {
        match self {
            Self::Status => "status",
            Self::Installations => "installations",
            Self::Recheck => "recheck",
            Self::Activate => "activate",
            Self::Stop => "stop",
            Self::Workspace => "workspace",
            Self::WorkspaceAccess => "workspace_access",
            Self::WorkspaceGrant => "workspace_grant",
        }
    }
}

#[derive(Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct Query {
    kind: Kind,
    pub(crate) guard_home: String,
    input: serde_json::Value,
}

pub(crate) fn evaluate(request: &Request, store: &PolicySnapshotStore) -> Result<Vec<u8>, String> {
    let digest = request_digest_with_limit(request, 64 * 1024)
        .map_err(|_| "native_context_assistance_request_too_large")?;
    let answer = (|| {
        validate(request, store)?;
        let home = Path::new(&request.query.guard_home);
        let service = store.context_assistance();
        if matches!(request.query.kind, Kind::Stop) {
            service.stop()?;
            crate::guard_config_update::disable_context_assistance(home)?;
        }
        let generation = service.configuration_generation()?;
        let settings = match crate::guard_config_load::context_assistance_config(home) {
            Ok(value) => value,
            Err(_) => {
                let repair = matches!(request.query.kind, Kind::Workspace | Kind::WorkspaceAccess)
                    && matches!(
                        request.query.input.get("action").and_then(|v| v.as_str()),
                        Some("data" | "clear" | "forget_history" | "forget_saved")
                    );
                if !repair {
                    service.configure_at(
                        AssistanceSettings::unavailable("configuration_unavailable"),
                        generation,
                    )?;
                    return Err("native_context_assistance_configuration_unavailable".into());
                }
                AssistanceSettings::unavailable("configuration_unavailable")
            }
        };
        service.configure_at(settings, generation)?;
        service.ensure_housekeeping(home);
        let data = if matches!(
            request.query.kind,
            Kind::Workspace | Kind::WorkspaceAccess | Kind::WorkspaceGrant
        ) {
            Some(service.workspace(
                home,
                store,
                request.query.input.clone(),
                matches!(request.query.kind, Kind::WorkspaceAccess),
                matches!(request.query.kind, Kind::WorkspaceGrant),
            )?)
        } else {
            None
        };
        match request.query.kind {
            Kind::Activate => service.schedule(Check::Activate, home.into())?,
            Kind::Recheck => service.schedule(Check::Recheck, home.into())?,
            Kind::Status
            | Kind::Installations
            | Kind::Stop
            | Kind::Workspace
            | Kind::WorkspaceAccess
            | Kind::WorkspaceGrant => {}
        }
        let mut state = service.status()?;
        if matches!(request.query.kind, Kind::Installations) {
            state["installation_options"] = json!(
                crate::policy_store::context_assistance_registry::list(home)?
            );
        }
        let mut payload = json!({"kind": request.query.kind.name(), "state": state});
        if let Some(data) = data {
            payload["data"] = data;
        }
        Ok(payload)
    })();
    response(request, &digest, answer)
}

fn validate(request: &Request, store: &PolicySnapshotStore) -> Result<(), String> {
    if request.schema != "guard-context-assistance-request.v1"
        || request.request_id.is_empty()
        || request.request_id.len() > 128
        || !Path::new(&request.query.guard_home).is_absolute()
    {
        return Err("native_context_assistance_request_invalid".into());
    }
    store.require_guard_home(&request.query.guard_home)?;
    if !matches!(
        request.query.kind,
        Kind::Workspace | Kind::WorkspaceAccess | Kind::WorkspaceGrant
    ) && request
        .query
        .input
        .as_object()
        .is_none_or(|input| !input.is_empty())
    {
        return Err("native_context_assistance_control_input_invalid".into());
    }
    Ok(())
}

pub(crate) fn reject_busy(
    request: &Request,
    store: &PolicySnapshotStore,
) -> Result<Vec<u8>, String> {
    let digest = request_digest_with_limit(request, 64 * 1024)
        .map_err(|_| "native_context_assistance_request_too_large")?;
    let code = validate(request, store)
        .err()
        .unwrap_or_else(|| "native_context_assistance_busy".into());
    response(request, &digest, Err(code))
}

fn response(
    request: &Request,
    digest: &str,
    answer: Result<serde_json::Value, String>,
) -> Result<Vec<u8>, String> {
    let response = match answer {
        Ok(payload) => {
            json!({"schema":"guard-context-assistance-result.v1", "request_id":request.request_id,
            "request_sha256":digest, "status":"ok", "code":"ok", "payload":payload})
        }
        Err(code) => {
            json!({"schema":"guard-context-assistance-result.v1", "request_id":request.request_id,
            "request_sha256":digest, "status":"error", "code":code, "payload":null})
        }
    };
    crate::encode_response(&response)
}

#[cfg(test)]
#[path = "context_assistance_op_tests.rs"]
mod tests;

use super::*;

pub(super) fn configure(
    shared: &Mutex<State>,
    mut settings: AssistanceSettings,
    generation: Option<u64>,
) -> Result<(), String> {
    let old = {
        let mut state = lock(shared)?;
        if state.closed {
            return Err("native_context_assistance_shutdown".into());
        }
        if generation.is_some_and(|generation| generation != state.generation) {
            return Err("native_context_assistance_context_stale".into());
        }
        // Stop revokes authority before waiting for cleanup or disk I/O. A
        // concurrent read of the older on-disk opt-in must not reverse it.
        if state.stopping {
            if !settings.requested.enabled && settings.diagnostic.is_none() {
                state.stopping = false;
                // Also invalidate readers that started during Stop and saw
                // the old disk bytes before opt-out was persisted.
                state.generation = state
                    .generation
                    .checked_add(1)
                    .ok_or("native_context_assistance_generation_exhausted")?;
            } else {
                settings.requested.enabled = false;
                settings.effective.enabled = false;
            }
        }
        if state.settings == settings {
            return Ok(());
        }
        if let Some(job) = &state.pending {
            job.cancel.store(true, Ordering::Release);
        }
        state.generation = state
            .generation
            .checked_add(1)
            .ok_or("native_context_assistance_generation_exhausted")?;
        state.settings = settings;
        state.error = None;
        state.last_check = None;
        revoke_runtime(&mut state)
    };
    await_cleanup(old);
    Ok(())
}

pub(super) fn await_cleanup(actor: Option<Arc<RuntimeActor<Engine>>>) -> bool {
    actor
        .as_ref()
        .is_none_or(|actor| actor.close_and_wait(Duration::from_millis(500)))
}

pub(super) fn start_watcher(
    weak: Weak<Mutex<State>>,
    generation: u64,
    home: PathBuf,
) -> std::io::Result<()> {
    std::thread::Builder::new()
        .name("guard-cigar-settings".into())
        .spawn(move || loop {
            std::thread::sleep(Duration::from_secs(1));
            let Some(shared) = weak.upgrade() else {
                break;
            };
            let old = {
                let Ok(mut state) = lock(&shared) else {
                    break;
                };
                if state.generation != generation || state.runtime.is_none() {
                    break;
                }
                if state.last_used.elapsed()
                    >= Duration::from_secs(u64::from(
                        state.settings.effective.limits.idle_shutdown_seconds,
                    ))
                {
                    state.error = Some("runtime_idle".into());
                    revoke_runtime(&mut state)
                } else if !state
                    .runtime
                    .as_ref()
                    .expect("runtime checked above")
                    .status()
                    .active
                {
                    // The actor owns heartbeats/SDK calls. Only atomic liveness is
                    // read while holding the settings state.
                    state.error = Some("runtime_closed".into());
                    revoke_runtime(&mut state)
                } else {
                    None
                }
            };
            if old.is_some() {
                await_cleanup(old);
                break;
            }
            let current = crate::guard_config_load::context_assistance_config(&home)
                .unwrap_or_else(|_| AssistanceSettings::unavailable("configuration_unavailable"));
            if configure(&shared, current, Some(generation)).is_err() {
                break;
            }
        })
        .map(|_| ())
}

impl Service {
    pub(crate) fn stop(&self) -> Result<(), String> {
        let old = {
            let mut state = lock(&self.state)?;
            state.stopping = true;
            if let Some(job) = &state.pending {
                job.cancel.store(true, Ordering::Release);
            }
            state.generation = state
                .generation
                .checked_add(1)
                .ok_or("native_context_assistance_generation_exhausted")?;
            state.settings.requested.enabled = false;
            state.settings.effective.enabled = false;
            state.error = None;
            state.last_check = None;
            revoke_runtime(&mut state)
        };
        await_cleanup(old);
        Ok(())
    }

    /// Resident teardown only. Reopening settings cannot restart this service.
    /// No persisted consent is changed, and no authority survives a new service.
    pub(crate) fn shutdown(&self) {
        let old = {
            // Poison recovery is limited to destructive in-memory cancellation.
            let mut state = self.state.lock().unwrap_or_else(|error| error.into_inner());
            state.closed = true;
            if let Some(job) = &state.pending {
                job.cancel.store(true, Ordering::Release);
            }
            state.generation = state.generation.saturating_add(1);
            state.settings.requested.enabled = false;
            state.settings.effective.enabled = false;
            state.last_check = None;
            revoke_runtime(&mut state)
        };
        await_cleanup(old);
    }
}

